    ('8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Quiz — Changer la vitesse, l’effort ou la nature du mouvement', 'Technologie', '3e', 'Les mécanismes de transmission et de transformation de mouvements', '29c9eb8a-65fb-5e2b-b039-ca6fe4d27389'::uuid),
