    ('a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'Quiz — Enlever, déformer, ajouter, assembler', 'Technologie', '3e', 'Procédés de fabrication', '44cac388-2bb4-586d-bf55-14ee0bfcd8ba'::uuid),
    ('4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Quiz — Travailler en atelier sans se blesser', 'Technologie', '3e', 'Règles de sécurité', '341f7f01-5c8a-55a3-9782-38c504395108'::uuid),
    ('ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Quiz — Séquence, condition, boucle, variable', 'Technologie', '3e', 'Bases de la programmation', '7d7dff82-9311-5f49-8fd6-224a92f80df2'::uuid),
    ('ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Quiz — Des blocs à assembler, ou des lignes à écrire', 'Technologie', '3e', 'Programmation graphique et programmation textuelle', 'db251617-63ed-5c7a-8d39-6f3b56e5add4'::uuid),
    ('03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Quiz — Du besoin au programme qui marche', 'Technologie', '3e', 'Écrire mettre au point et exécuter un programme simple', 'a24ab612-6a58-51cf-befc-da0f9d8b7987'::uuid),
    ('cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Quiz — Organiser pour pouvoir chercher', 'Technologie', '3e', 'Structuration et traitement des données', 'f54d729c-d2cc-53ca-85b1-2aca52175f52'::uuid),
    ('e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'Quiz — Où vivent les données, et qui y a droit', 'Technologie', '3e', 'Système d’information et stockage de données', 'c118ed9d-885b-5bfb-825b-11adcfb6fc85'::uuid),
    ('f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Quiz — Comment un message va d’une machine à l’autre', 'Technologie', '3e', 'La circulation de l’information dans un réseau informatique', 'e0549f7b-d396-53ab-ab8a-0eeebf94e6a9'::uuid),
    ('ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Quiz — Des tâches, des délais, une équipe', 'Technologie', '3e', 'Organisation d’un projet technique', 'e864e96b-c73f-520c-b1bd-94aca8658103'::uuid),
    ('257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Quiz — Dessiner pour se faire comprendre', 'Technologie', '3e', 'Modes de représentation d’un OST', '0e4871f9-40a4-524a-afa0-3a080058c08b'::uuid),
    ('e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Quiz — De l’idée à l’objet réel', 'Technologie', '3e', 'Concevoir et fabriquer un OST', 'a9c72af7-7226-583f-afb7-92371d973f8e'::uuid),
    ('954af929-2128-5885-a048-77b52971190d'::uuid, 'Quiz — Prouver que l’objet fait ce qu’on a promis', 'Technologie', '3e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', '722f2c6e-290b-54b6-a1ea-6b3973f1b0d6'::uuid),
    ('41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Quiz — Fabriquer pour apprendre, avant de fabriquer pour vendre', 'Technologie', '3e', 'Prototypage de solutions', '4693ad3e-6f38-575b-b284-166d2328eb86'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('6597b29c-dfb5-55a0-bbcf-e6b0bad177b6'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'Que signifie le sigle OST ?', 'mcq', '["Objet et Système Technique","Organisation Standard du Travail","Outil de Simulation Technique","Objet Sans Transformation"]'::jsonb, 0, 'C’est le vocabulaire employé tout au long du programme.', 1),
    ('4e7ae3a9-b1bf-5474-a25c-999c27d20820'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'Qu’est-ce qui distingue un système technique d’un objet technique ?', 'mcq', '["Il associe plusieurs objets qui travaillent ensemble","Il est toujours plus grand","Il ne consomme pas d’énergie","Il n’a pas d’utilisateur"]'::jsonb, 0, 'Un ascenseur ou une alarme sont des systèmes.', 2),
    ('1bbe6703-3fc6-5d20-a6ca-8bd7531862a3'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'À quelle question répond la fonction d’usage d’un objet ?', 'mcq', '["Dans quel but l’objet est-il utilisé ?","Combien coûte-t-il ?","De quel matériau est-il fait ?","Qui l’a inventé ?"]'::jsonb, 0, 'Elle complète « à qui rend-il service » et « sur quoi agit-il ».', 3),
    ('9b3c03c1-80f4-5acd-8b25-6f9f1a6b786e'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'Qu’est-ce qui fait évoluer un objet technique ?', 'mcq', '["Les besoins, le progrès technique, les contraintes économiques et environnementales","Uniquement la mode","Uniquement le prix des matériaux","Rien : un objet réussi ne change plus"]'::jsonb, 0, 'Ces quatre moteurs jouent ensemble.', 4),
    ('d4dc565d-05e1-5d23-9dd1-fda51b920c05'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'Qu’est-ce qu’une famille d’objets techniques ?', 'mcq', '["Des objets qui remplissent la même fonction d’usage par des solutions différentes","Des objets fabriqués par la même entreprise","Des objets vendus au même prix","Des objets du même matériau"]'::jsonb, 0, 'Bougie, lampe à huile, ampoule et LED forment une famille.', 5),
    ('27e8f5c6-b8ae-531e-950f-200f6f0324bb'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'Qu’est-ce qu’une lignée d’objets techniques ?', 'mcq', '["Un objet suivi dans ses améliorations successives au fil du temps","Une gamme de produits d’une marque","Une chaîne de fabrication","Un classement par prix"]'::jsonb, 0, 'Elle raconte l’histoire d’un même objet.', 6),
    ('7657c5a2-13d7-5aad-a907-154a8b8f3023'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'Qu’est-ce qu’un besoin, en technologie ?', 'mcq', '["Ce qui justifie l’existence de l’objet technique","Le prix maximal accepté par l’acheteur","La quantité d’énergie consommée","Le nombre de pièces de l’objet"]'::jsonb, 0, 'Tout OST naît d’un besoin à satisfaire.', 7),
    ('74946267-625b-521a-b227-ae659a3f50bb'::uuid, 'e214e37a-9903-591e-b0c7-49cdd6580ccb'::uuid, 'Un objet technique existe indépendamment de tout besoin humain.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est conçu et fabriqué précisément pour satisfaire un besoin.', 8),
    ('fa9dfc62-432d-56a1-a0b0-c4e48cf13893'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Qu’est-ce que la fonction d’usage d’un objet ?', 'mcq', '["Le service qu’il rend à l’utilisateur","Le phénomène physique qu’il exploite","Le composant qui le réalise","Son prix de revient"]'::jsonb, 0, 'Elle s’exprime par un verbe à l’infinitif.', 1),
    ('11e4a329-a0b1-5030-8d9e-8fa42b35eb99'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Qu’est-ce qu’une fonction technique ?', 'mcq', '["Ce que l’objet doit assurer en interne pour remplir sa fonction d’usage","Le service rendu à l’utilisateur","Le matériau employé","Le mode d’emploi"]'::jsonb, 0, 'Transmettre le mouvement, freiner, diriger, pour un vélo.', 2),
    ('1adb12c6-7ecd-53be-8d57-374a0e1bd9c3'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Qu’est-ce qu’un principe technique ?', 'mcq', '["Le phénomène physique utilisé pour réaliser une fonction","Le composant concret retenu","Le service rendu","La norme à respecter"]'::jsonb, 0, 'Le frottement pour freiner, l’électromagnétisme pour produire du courant.', 3),
    ('2c7ba2ea-771d-5088-876f-722377b1fdcc'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Qu’est-ce qu’une solution technique ?', 'mcq', '["Le composant concret retenu pour réaliser une fonction","Le besoin de l’utilisateur","Le phénomène physique exploité","La durée de vie de l’objet"]'::jsonb, 0, 'Frein à patins ou frein à disque : deux solutions, un même principe.', 4),
    ('b4752bb5-b3b0-5ad4-9ea9-a71af1d2d7f9'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Combien de solutions techniques une même fonction peut-elle avoir ?', 'mcq', '["Plusieurs","Une seule","Aucune","Autant que d’utilisateurs"]'::jsonb, 0, 'C’est ce qui rend la comparaison possible en conception.', 5),
    ('272dd061-8978-57e2-b90e-601fe4042486'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Qu’est-ce qui rend une exigence du cahier des charges vérifiable ?', 'mcq', '["Un critère mesurable et un niveau chiffré","Une description détaillée","Un dessin de l’objet","La signature du client"]'::jsonb, 0, 'Sans niveau chiffré, une exigence n’est qu’un vœu.', 6),
    ('ffae6034-5eef-5559-9200-11706e076ee1'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Comment représente-t-on le lien entre fonctions et solutions ?', 'mcq', '["Par un diagramme ou un arbre des fonctions","Par un graphique en camembert","Par un chronogramme","Par une carte du réseau"]'::jsonb, 0, 'Fonction d’usage → fonctions techniques → solutions techniques.', 7),
    ('70cfe113-55c2-51f3-86fc-723334b15069'::uuid, '6862ede8-1d94-514a-990d-51e25e9a726b'::uuid, 'Une fonction d’usage et une fonction technique désignent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’une regarde l’utilisateur, l’autre l’intérieur de l’objet.', 8),
    ('0bd36ba9-bb63-58b2-9363-59a1e1ede36e'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Quelle est la première étape du cycle de vie d’un objet ?', 'mcq', '["L’extraction des matières premières","La fabrication","La distribution","L’utilisation"]'::jsonb, 0, 'Le cycle commence bien avant l’usine.', 1),
    ('3c5dcdc3-3a95-53bb-aa50-87d837d9eadd'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Que mesure une analyse du cycle de vie (ACV) ?', 'mcq', '["Les impacts environnementaux de l’objet à toutes ses étapes","Le prix de vente de l’objet","La durée de la garantie","Le nombre de pièces de l’objet"]'::jsonb, 0, 'Elle permet de comparer deux objets sans se limiter à leur usage.', 2),
    ('12b2121b-cff2-598c-a75c-997beae3bfde'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Qu’est-ce que l’économie circulaire ?', 'mcq', '["Un modèle qui réduit, réemploie et recycle pour refermer la boucle","Un modèle qui produit toujours plus","Le commerce entre pays voisins","La vente d’objets d’occasion uniquement"]'::jsonb, 0, 'Elle s’oppose au modèle linéaire extraire-fabriquer-jeter.', 3),
    ('ee3db9a2-434f-5ad3-8e8c-da35474c3a19'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Que désignent les DEEE ?', 'mcq', '["Les déchets d’équipements électriques et électroniques","Les déchets d’emballages en entreprise","Les données d’économie énergétique","Les documents d’étude environnementale"]'::jsonb, 0, 'Ils se déposent en déchèterie ou en point de collecte.', 4),
    ('c7f606fc-8699-5d3d-8fd6-c7d5a8961d00'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Quelle étape du cycle de vie consomme souvent le plus d’énergie pour un appareil électroménager ?', 'mcq', '["L’utilisation","La distribution","La fin de vie","L’emballage"]'::jsonb, 0, 'D’où l’importance des étiquettes énergie.', 5),
    ('880720a0-a1f7-5939-9775-f505f84a8d9e'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Qu’est-ce que la valorisation énergétique d’un déchet ?', 'mcq', '["Récupérer de l’énergie en le brûlant","Le revendre d’occasion","Le broyer pour en faire une matière première","L’enfouir sous terre"]'::jsonb, 0, 'C’est une solution moins bonne que le recyclage, meilleure que l’enfouissement.', 6),
    ('d7a05c7a-ad59-58f6-b9ea-f79756c11ef1'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Qu’est-ce que l’indice de réparabilité ?', 'mcq', '["Une note obligatoire indiquant si un produit est facile à réparer","Le nombre de réparations effectuées","La durée de la garantie légale","Le prix des pièces détachées"]'::jsonb, 0, 'Il lutte contre l’obsolescence en informant l’acheteur.', 7),
    ('c96d6066-c976-5ccd-8260-3e6bc6a3c90f'::uuid, '57cdd485-00d4-5659-ad4b-95e1618db784'::uuid, 'Un objet non cassé ne peut pas devenir inutilisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’obsolescence logicielle ou l’absence de pièces détachées suffit à le rendre inutilisable.', 8),
    ('b9dd26fa-88fc-543e-af2a-04a4a54da20d'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'Qu’est-ce qu’un interacteur ?', 'mcq', '["Un élément de l’environnement en relation avec l’objet technique","Une pièce interne de l’objet","Un logiciel de conception","Un défaut de fabrication"]'::jsonb, 0, 'Utilisateur, énergie, milieu, normes, budget en sont.', 1),
    ('671f6812-1e4d-599d-b9c5-4fa70db08fd3'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'Que relie une fonction principale dans un diagramme des interacteurs ?', 'mcq', '["Deux interacteurs à travers l’objet","L’objet à un seul interacteur","Deux objets entre eux","L’objet à son fabricant"]'::jsonb, 0, 'C’est la raison d’être de l’objet.', 2),
    ('423c0f35-200a-54d9-94b0-122f8d414f73'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'Que relie une fonction contrainte ?', 'mcq', '["L’objet à un seul interacteur","Deux interacteurs entre eux","Deux fonctions principales","L’utilisateur au fabricant"]'::jsonb, 0, 'Résister à la pluie, respecter une norme, tenir dans un budget.', 3),
    ('233f5a1d-2f14-564c-a623-d3d0c593c1fb'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'Quelle est la fonction principale d’un lampadaire de rue ?', 'mcq', '["Permettre au piéton de voir la chaussée la nuit","Résister aux intempéries","Respecter le budget de la commune","S’intégrer au paysage urbain"]'::jsonb, 0, 'Les trois autres propositions sont des fonctions contraintes.', 4),
    ('6760e61f-e17f-5809-9c74-0d124e1dc484'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'Où place-t-on l’objet dans un diagramme des interacteurs ?', 'mcq', '["Au centre, les interacteurs autour","En haut, les interacteurs en dessous","À gauche, comme point de départ","À l’extérieur du diagramme"]'::jsonb, 0, 'Les liaisons partent de lui vers son environnement.', 5),
    ('8aaf662a-41b0-5df3-9e71-278f1c5be46c'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'À quoi sert le diagramme des interacteurs ?', 'mcq', '["À établir le cahier des charges de l’objet","À dessiner l’objet en trois dimensions","À calculer son prix de revient","À programmer son microcontrôleur"]'::jsonb, 0, 'Chaque fonction identifiée devient une exigence à mesurer.', 6),
    ('ff08e4cc-ba84-57df-8cec-bc3c0d5f135e'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'Qu’appelle-t-on la matière d’œuvre d’un objet technique ?', 'mcq', '["Ce sur quoi l’objet agit","Le matériau dont il est fait","L’énergie qu’il consomme","L’outil qui l’a fabriqué"]'::jsonb, 0, 'Pour un sèche-cheveux, ce sont les cheveux, pas le plastique du boîtier.', 7),
    ('f43f06e8-d3b4-56f3-aa9d-4ad50311d0df'::uuid, '8574fecb-6596-55d2-81c0-5816d1239d8d'::uuid, 'Un objet qui remplit sa fonction principale remplit forcément son cahier des charges.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doit aussi satisfaire toutes ses fonctions contraintes.', 8),
    ('fd106e37-ad4e-595a-b211-ddab7d03dfcd'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'Qu’est-ce qu’une contrainte, en technologie ?', 'mcq', '["Une exigence imposée au concepteur, qui limite ses choix","Un défaut de l’objet","Une panne en cours d’usage","Le prix de vente conseillé"]'::jsonb, 0, 'Elle doit être respectée par la solution retenue.', 1),
    ('688828f8-e412-5bd5-a889-b61fb204654f'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'Quel document rassemble toutes les exigences d’un projet ?', 'mcq', '["Le cahier des charges fonctionnel","La notice d’utilisation","Le plan de fabrication","Le devis"]'::jsonb, 0, 'Chaque fonction y porte un critère, un niveau et une flexibilité.', 2),
    ('2cda193a-4739-5163-9817-46856175c73e'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'Que doit comporter une exigence bien rédigée ?', 'mcq', '["Un critère mesurable et un niveau chiffré","Un adjectif qualificatif","Un dessin","Le nom du fabricant"]'::jsonb, 0, '« Masse inférieure à 300 g » plutôt que « le plus léger possible ».', 3),
    ('7ed5db27-3e71-5860-9482-e761e0ba0134'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'À quelle famille appartient la contrainte « respecter la norme CE » ?', 'mcq', '["Aux contraintes réglementaires et normatives","Aux contraintes esthétiques","Aux contraintes ergonomiques","Aux contraintes économiques"]'::jsonb, 0, 'Les normes s’imposent au concepteur.', 4),
    ('dcadb26c-636a-57e5-ab84-332703acfc67'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'À quelle famille appartient la contrainte « être utilisable par une personne en fauteuil » ?', 'mcq', '["Aux contraintes ergonomiques","Aux contraintes économiques","Aux contraintes techniques","Aux contraintes esthétiques"]'::jsonb, 0, 'L’accessibilité relève du confort et de l’usage.', 5),
    ('caaca60e-b3fa-5c70-b08f-d98e1fea2f5e'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'Que signifie la flexibilité d’une exigence ?', 'mcq', '["La tolérance acceptée sur le niveau à atteindre","La souplesse du matériau","La durée de la garantie","Le nombre de solutions possibles"]'::jsonb, 0, 'F0 impératif, F1 peu négociable, F2 négociable.', 6),
    ('4acaf29e-6e90-5b14-b59e-aa1de9ff687c'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'Pourquoi concevoir suppose-t-il d’arbitrer ?', 'mcq', '["Parce que certaines contraintes s’opposent entre elles","Parce que le client change d’avis","Parce que les normes évoluent chaque année","Parce que les matériaux manquent toujours"]'::jsonb, 0, 'Alléger un objet le rend souvent moins résistant ou plus cher.', 7),
    ('c30fbd20-2b34-5945-b436-baff74bb0c11'::uuid, '216c9318-a791-59be-8dfe-26d7b72861f6'::uuid, 'Une contrainte peut être vérifiée même si elle n’est pas mesurable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans critère chiffré, aucun essai ne peut conclure.', 8),
    ('7ad31b96-8bec-5ad0-8fea-935e0787274f'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'Quel outil sert à comparer plusieurs solutions techniques ?', 'mcq', '["Un tableau multicritère","Un diagramme des interacteurs","Un chronogramme","Un schéma de câblage"]'::jsonb, 0, 'Solutions en colonnes, critères en lignes.', 1),
    ('cc1f1b9a-4f2a-5b77-ad32-4dd51ae2cd96'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'À quoi sert la pondération dans un tableau comparatif ?', 'mcq', '["À donner plus de poids aux critères les plus importants","À augmenter le nombre de solutions","À réduire le nombre de critères","À calculer le prix de vente"]'::jsonb, 0, 'Sans elle, prix et sécurité pèseraient autant.', 2),
    ('85a2b7ce-4ff3-5a2b-966b-a69c87a24c10'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'Qu’est-ce que le coût global d’un objet ?', 'mcq', '["Le prix d’achat plus les coûts d’usage et d’entretien","Le prix d’achat seul","Le coût de fabrication","Le coût de recyclage"]'::jsonb, 0, 'Une LED chère à l’achat revient moins cher sur sa durée de vie.', 3),
    ('581a4ccd-ceee-5430-b1e7-86ddde8e6406'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'Comment justifie-t-on correctement un choix technique ?', 'mcq', '["En le confrontant aux exigences du cahier des charges","En invoquant le goût du concepteur","En choisissant la solution la moins chère","En prenant la solution la plus récente"]'::jsonb, 0, 'Les critères impératifs (F0) départagent d’abord.', 4),
    ('8522c5a6-a162-5c18-9f87-a8639e50946e'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'Quel critère mesure le temps de fonctionnement sans panne ?', 'mcq', '["La fiabilité","L’ergonomie","L’encombrement","L’esthétique"]'::jsonb, 0, 'Elle est souvent liée à la durée de vie annoncée.', 5),
    ('145fa9fb-4883-5ae5-a483-82af9f36b2d0'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'Pourquoi la réparabilité est-elle devenue un critère de choix ?', 'mcq', '["Parce qu’elle allonge la durée de vie et réduit les déchets","Parce qu’elle diminue le prix d’achat","Parce qu’elle accélère la fabrication","Parce qu’elle améliore l’esthétique"]'::jsonb, 0, 'Un indice de réparabilité est désormais obligatoire sur plusieurs familles de produits.', 6),
    ('2eab0130-09c9-5ca8-a8b8-ed9d08f06755'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'Quel critère relève de l’impact environnemental ?', 'mcq', '["La recyclabilité des matériaux","Le confort d’utilisation","La rapidité de fabrication","Le style du produit"]'::jsonb, 0, 'Consommation d’énergie et matériaux employés en relèvent aussi.', 7),
    ('6f3c591c-092c-5114-91fa-54ee9e2118e9'::uuid, '8e4d0b6d-fb84-5969-b002-c1859fbba544'::uuid, 'La solution la moins chère à l’achat est toujours la plus économique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le coût global inclut l’énergie, les consommables et l’entretien.', 8),
    ('ba5056b6-9a7c-5f06-b82a-d183837a0740'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Quelles sont les quatre fonctions de la chaîne d’énergie, dans l’ordre ?', 'mcq', '["Alimenter, distribuer, convertir, transmettre","Acquérir, traiter, communiquer, agir","Convertir, alimenter, transmettre, distribuer","Alimenter, convertir, distribuer, agir"]'::jsonb, 0, 'Elle se termine par l’action produite.', 1),
    ('cea0a053-7a46-5be2-a78d-711e796c3f8d'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Quelle fonction assure un interrupteur ou un relais ?', 'mcq', '["Distribuer","Alimenter","Convertir","Transmettre"]'::jsonb, 0, 'Ils laissent passer ou interrompent l’énergie.', 2),
    ('62ab4d5c-6344-5bb9-a864-40a3b5b6adfa'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Quelle fonction assure un moteur électrique ?', 'mcq', '["Convertir","Alimenter","Distribuer","Transmettre"]'::jsonb, 0, 'Il transforme l’énergie électrique en énergie mécanique.', 3),
    ('3dd33422-f768-597c-9541-cd6cdf42cfec'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Comment appelle-t-on les composants qui convertissent l’énergie ?', 'mcq', '["Les actionneurs","Les capteurs","Les interfaces","Les protocoles"]'::jsonb, 0, 'Moteur, vérin, lampe, résistance chauffante.', 4),
    ('503e708d-4736-539d-8565-011a52cb2ee7'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Quelle fonction assurent des engrenages ou une courroie ?', 'mcq', '["Transmettre","Convertir","Alimenter","Distribuer"]'::jsonb, 0, 'Ils acheminent l’énergie mécanique en adaptant vitesse et effort.', 5),
    ('718f117e-dec7-5091-bd26-01c90aa0a00f'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Quelle source d’énergie assure la fonction « alimenter » d’un objet nomade ?', 'mcq', '["Une batterie","Un engrenage","Un relais","Un capteur"]'::jsonb, 0, 'Pile, batterie ou panneau solaire selon les cas.', 6),
    ('a8968066-e1d0-55b3-a5ed-d04bb0221394'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Où les chaînes d’énergie et d’information se rejoignent-elles ?', 'mcq', '["À la fonction « distribuer », qui reçoit l’ordre de la partie commande","À la fonction « alimenter »","À la fonction « transmettre »","Elles ne se rejoignent jamais"]'::jsonb, 0, 'La chaîne d’information décide, la chaîne d’énergie agit.', 7),
    ('6d2eaaae-0898-58d6-943e-69a9c2eb1736'::uuid, '650a1364-ce95-50fc-bb6f-d4a8b8c75609'::uuid, 'Un vérin pneumatique appartient à la fonction « transmettre ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un actionneur : il convertit l’énergie pneumatique en énergie mécanique.', 8),
    ('736ca993-204d-5df5-b274-6ec8af712d03'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Quelle différence y a-t-il entre transmettre et transformer un mouvement ?', 'mcq', '["Transmettre conserve la nature du mouvement, transformer la change","Transmettre change la nature, transformer conserve la vitesse","Ce sont deux mots pour la même chose","Transmettre concerne l’électricité, transformer la mécanique"]'::jsonb, 0, 'Rotation vers rotation, ou rotation vers translation.', 1),
    ('ac25ce44-cfdc-5e22-9101-dd012f3a7b61'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Dans quel sens tournent deux roues dentées en contact ?', 'mcq', '["En sens inverse l’une de l’autre","Dans le même sens","Elles ne tournent pas","Cela dépend de leur diamètre"]'::jsonb, 0, 'Sauf avec une roue intermédiaire ou un engrenage intérieur.', 2),
    ('61822941-4092-59e9-b3d6-d7471550a8b2'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Quel système de transmission n’a aucun risque de glissement ?', 'mcq', '["Pignons et chaîne","Poulies et courroie","Roues de friction","Courroie croisée"]'::jsonb, 0, 'C’est la transmission du vélo.', 3),
    ('544bd48b-8679-5789-a443-02da6d45de23'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Comment calcule-t-on le rapport de transmission ?', 'mcq', '["Vitesse de sortie ÷ vitesse d’entrée","Vitesse d’entrée × vitesse de sortie","Nombre de dents de sortie × vitesse d’entrée","Diamètre de sortie + diamètre d’entrée"]'::jsonb, 0, 'Il vaut aussi le nombre de dents de l’entrée divisé par celui de la sortie.', 4),
    ('5722d203-f26d-5a31-a33d-def7697dfd0f'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Que fait un réducteur ?', 'mcq', '["Il diminue la vitesse et augmente la force","Il augmente la vitesse et diminue la force","Il inverse le sens du mouvement","Il transforme la rotation en translation"]'::jsonb, 0, 'Son rapport de transmission est inférieur à 1.', 5),
    ('9dd5fa99-f5d3-5426-806a-fbdcbf4165cd'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Quel système transforme une rotation en translation ?', 'mcq', '["Le pignon-crémaillère","Les poulies-courroie","Les pignons-chaîne","Les roues de friction"]'::jsonb, 0, 'Le système vis-écrou et la bielle-manivelle aussi.', 6),
    ('1e888fee-8c17-57d2-8859-df9d9af102f3'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Quel système équipe un moteur thermique pour transformer le mouvement des pistons ?', 'mcq', '["La bielle-manivelle","Le pignon-crémaillère","La vis sans fin","La courroie croisée"]'::jsonb, 0, 'Il convertit la translation alternative en rotation.', 7),
    ('59666fab-6e84-525d-9eed-beabf335c53b'::uuid, '8b840e59-7054-579c-a48a-2e2a0d91b322'::uuid, 'Une transmission par courroie ne peut jamais glisser.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le glissement est justement son principal inconvénient face à la chaîne.', 8),
    ('fe442283-4497-5b5d-ba7e-457d760dcbe0'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'À quelle famille appartient le verre ?', 'mcq', '["Aux céramiques","Aux métalliques","Aux organiques","Aux composites"]'::jsonb, 0, 'Dur, résistant à la chaleur, mais fragile.', 1),
    ('89da3f8a-98c3-558d-9dfb-c832ff2dd527'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'Qu’est-ce qu’un matériau composite ?', 'mcq', '["Un matériau associant deux matériaux pour cumuler leurs qualités","Un matériau recyclé","Un métal allié à un autre métal","Un plastique coloré"]'::jsonb, 0, 'Fibre de carbone dans une résine, béton armé, contreplaqué.', 2),
    ('00756b41-114f-5b59-bde2-9171cbb56399'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'Que mesure la dureté d’un matériau ?', 'mcq', '["Sa résistance à la rayure","Sa capacité à revenir à sa forme initiale","Sa masse par unité de volume","Sa conductivité électrique"]'::jsonb, 0, 'À ne pas confondre avec la résistance mécanique.', 3),
    ('0bd23b43-eb22-53ec-9cfd-65fb57bc4700'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'Que signifie l’élasticité d’un matériau ?', 'mcq', '["Il reprend sa forme après déformation","Il se raye difficilement","Il conduit bien la chaleur","Il résiste à la corrosion"]'::jsonb, 0, 'Au-delà d’une limite, la déformation devient permanente.', 4),
    ('5ab88d06-a853-5d9f-80cf-bc9313f0fda1'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'Quelle propriété décide de la légèreté d’une pièce ?', 'mcq', '["La masse volumique du matériau","Sa dureté","Sa conductivité","Son élasticité"]'::jsonb, 0, 'C’est la masse par unité de volume.', 5),
    ('8cb20f49-7ff3-510e-a7b0-34f2999ae2a6'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'Quel procédé convient à un thermoplastique ?', 'mcq', '["L’injection","Le soudage à l’arc","Le forgeage","Le sciage à la scie à métaux"]'::jsonb, 0, 'Extrusion, thermoformage et impression 3D également.', 6),
    ('70f0644e-d5a3-5ddb-955a-65d914b6a76d'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'Quel avantage environnemental présente l’aluminium ?', 'mcq', '["Il se recycle presque indéfiniment","Il ne consomme pas d’énergie à produire","Il se dégrade naturellement","Il ne nécessite aucune extraction"]'::jsonb, 0, 'Sa production initiale reste, elle, très énergivore.', 7),
    ('d14bd78f-a0fe-59c7-8a65-80d976a83246'::uuid, '27a9e585-02f4-54d3-b1b6-fdce8f80485e'::uuid, 'Il existe un matériau meilleur que tous les autres en toutes circonstances.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On choisit selon le profil de propriétés exigé par le cahier des charges.', 8),
    ('cf5eed4d-1336-5cbc-823f-b59b937d476e'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'Quelles sont les trois fonctions de la chaîne d’information ?', 'mcq', '["Acquérir, traiter, communiquer","Alimenter, distribuer, convertir","Capter, convertir, agir","Mesurer, calculer, imprimer"]'::jsonb, 0, 'Capteurs, partie commande, moyens de communication.', 1),
    ('b9fe02e0-08f8-574f-8b17-3ce59ecf526a'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'À quelle fonction correspond un capteur ?', 'mcq', '["Acquérir","Traiter","Communiquer","Convertir"]'::jsonb, 0, 'Il recueille une information sur l’environnement ou le système.', 2),
    ('75b0495e-f603-5262-a698-a026beaa2bca'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'Quel composant assure la fonction « traiter » ?', 'mcq', '["Le microcontrôleur","Le capteur de température","Le moteur","La LED"]'::jsonb, 0, 'Il exécute le programme et prend les décisions.', 3),
    ('8d475592-2c6e-5904-bfa9-6e823a2b46a1'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'Quelle est la différence entre un capteur et un actionneur ?', 'mcq', '["Le capteur prend une information, l’actionneur produit une action","Le capteur produit une action, l’actionneur mesure","Ils appartiennent tous deux à la chaîne d’énergie","Ils font la même chose"]'::jsonb, 0, 'L’un est dans la chaîne d’information, l’autre dans la chaîne d’énergie.', 4),
    ('930fd96c-6ddd-50c0-8e2f-ceec23cdca44'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'À quelle fonction appartient un écran d’affichage ?', 'mcq', '["Communiquer","Acquérir","Traiter","Transmettre"]'::jsonb, 0, 'Il transmet l’information à l’utilisateur.', 5),
    ('30b94692-614c-5b5b-b256-76430175b8ac'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'Quel capteur mesure une distance sans contact ?', 'mcq', '["Le capteur à ultrasons","Le bouton-poussoir","Le capteur de température","Le fin de course"]'::jsonb, 0, 'Il mesure le temps de retour de l’écho.', 6),
    ('14b4e4fb-7715-5c11-bc11-dd5f570b58da'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'Que doit garantir un objet connecté au-delà de sa fonction ?', 'mcq', '["La sécurité des données personnelles qu’il transmet","Une durée de vie illimitée","L’absence de programme interne","Une consommation nulle"]'::jsonb, 0, 'Un objet connecté mal protégé est une porte d’entrée pour le piratage.', 7),
    ('a754f574-7d97-5915-82e0-70b34674701d'::uuid, 'd6c5a8c9-1ec2-58d1-bfbd-9e735aa6550d'::uuid, 'Un bouton-poussoir est un actionneur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le plus simple des capteurs : il capte l’action de l’utilisateur.', 8),
    ('d98ec4a3-262e-5824-95bf-6a8be7e1a006'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'À quelle famille appartient le perçage ?', 'mcq', '["À l’enlèvement de matière","À la déformation","À l’ajout de matière","À l’assemblage"]'::jsonb, 0, 'Il produit des copeaux : de la matière est perdue.', 1),
    ('f0848369-56de-5139-a056-b7dc3545e2ee'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'À quelle famille appartient le pliage ?', 'mcq', '["À la déformation","À l’enlèvement de matière","À l’ajout de matière","À l’assemblage"]'::jsonb, 0, 'La matière change de forme sans être retirée.', 2),
    ('00c410fa-aa66-566a-afa6-10793ed33e41'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'Comment appelle-t-on la fabrication par ajout de matière ?', 'mcq', '["L’impression 3D, ou fabrication additive","Le fraisage","L’emboutissage","Le rivetage"]'::jsonb, 0, 'La matière est déposée couche par couche.', 3),
    ('d0be486d-068d-573c-b5e2-992a69cf3ce8'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'Quel assemblage permet de réparer et de recycler l’objet ?', 'mcq', '["Un assemblage démontable par vis ou clips","Une soudure","Un rivetage","Un collage"]'::jsonb, 0, 'Les assemblages non démontables sont définitifs.', 4),
    ('339a58b6-a8b1-5bd0-8c51-46c4f3dd752f'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'Que garantit une machine à commande numérique ?', 'mcq', '["La répétabilité et la précision des pièces produites","L’absence totale de déchets","Un coût nul","Une fabrication sans programme"]'::jsonb, 0, 'Elle exécute un programme issu du dessin numérique.', 5),
    ('a3107c4a-1dfb-55b7-8391-cc4bdbf2ad63'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'Quel procédé convient le mieux à une pièce unique de forme complexe ?', 'mcq', '["L’impression 3D","L’injection plastique","L’emboutissage","Le moulage en série"]'::jsonb, 0, 'Les procédés de série exigent un outillage coûteux.', 6),
    ('ca37a98b-1b1b-5c51-aa20-7ab153f35310'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'Quel critère décide principalement du choix d’un procédé ?', 'mcq', '["La quantité de pièces à produire","La couleur souhaitée","Le nom du fabricant","La date de livraison seule"]'::jsonb, 0, 'Matériau, forme, précision et coût interviennent également.', 7),
    ('a6638a86-06b3-5a53-aee4-2715280f00d2'::uuid, 'a180c944-6117-5bec-a3a1-74264dba8d73'::uuid, 'La fabrication par déformation produit beaucoup de copeaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’enlèvement de matière qui en produit ; la déformation n’en perd pas.', 8),
    ('406ef83c-fd76-5a41-a63e-29cc4f8c9c7e'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Quand porte-t-on des lunettes de protection ?', 'mcq', '["Dès qu’une opération peut projeter des éclats","Uniquement lors des soudures","Seulement si la machine est bruyante","Uniquement en cas de produits chimiques"]'::jsonb, 0, 'Perçage, sciage et meulage projettent des particules.', 1),
    ('0b0b4f94-80e6-5409-9cbe-59488c1b35bd'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Pourquoi ne porte-t-on pas de gants près d’une pièce en rotation ?', 'mcq', '["Parce qu’ils peuvent être happés par la pièce","Parce qu’ils réduisent la précision","Parce qu’ils s’usent trop vite","Parce qu’ils isolent du courant"]'::jsonb, 0, 'Le gant entraîne alors la main avec lui.', 2),
    ('fdf6f9ac-f8ec-59d9-ad93-1286e59e4388'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Que faut-il vérifier avant de démarrer une machine ?', 'mcq', '["Que les carters et protections sont en place","Que la salle est vide","Que la pièce est peinte","Que le programme est enregistré"]'::jsonb, 0, 'Et savoir où se trouve l’arrêt d’urgence.', 3),
    ('2bd82727-8ce3-5c61-8ee0-8bf26614cb81'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Quand peut-on régler ou nettoyer une machine ?', 'mcq', '["Uniquement à l’arrêt complet","Pendant qu’elle tourne au ralenti","Dès que l’enseignant est présent","À tout moment avec des gants"]'::jsonb, 0, 'C’est la règle la plus enfreinte et la principale cause d’accidents.', 4),
    ('bc65be56-47e7-5b47-ae60-df4cc81c7462'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Que signifie un pictogramme en triangle jaune ?', 'mcq', '["Un danger","Une obligation","Une interdiction","Une information de secours"]'::jsonb, 0, 'Le rond bleu signale une obligation, le rond rouge barré une interdiction.', 5),
    ('42e000bb-d32b-59a1-aab9-0582687cb5d7'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Que signifie un pictogramme rond bleu ?', 'mcq', '["Une obligation, comme le port des lunettes","Un danger électrique","Une interdiction","Une issue de secours"]'::jsonb, 0, 'Le bleu impose un comportement ou un équipement.', 6),
    ('8bc8cae6-73fc-5d7b-942a-7a3bf5922173'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Que doit-on savoir avant de démarrer une machine ?', 'mcq', '["Où se trouve le bouton d’arrêt d’urgence","Le prix de la machine","Le nom du fabricant","La durée totale de l’opération"]'::jsonb, 0, 'Le chercher pendant l’incident est déjà trop tard.', 7),
    ('d111f563-89c3-5576-8338-01b70e26009f'::uuid, '4e789853-2f82-52fd-ac86-3aeec744e5ca'::uuid, 'Deux élèves peuvent travailler simultanément sur la même machine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un seul opérateur à la fois, et sans être distrait.', 8),
    ('f355c8d6-8d0b-53df-9bae-df1c047e39e6'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Qu’est-ce qu’un algorithme ?', 'mcq', '["Une suite d’instructions permettant d’obtenir un résultat","Un langage de programmation","Un composant électronique","Un logiciel de dessin"]'::jsonb, 0, 'Le programme en est la traduction pour la machine.', 1),
    ('d2175a8e-5377-5b31-8598-029108616a92'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Quelle structure permet d’exécuter des instructions seulement dans certains cas ?', 'mcq', '["La condition","La séquence","La boucle bornée","La variable"]'::jsonb, 0, 'Elle repose sur un test vrai ou faux.', 2),
    ('ac57082b-1873-5f4b-ab92-23e0fda567e2'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Qu’est-ce qu’une boucle bornée ?', 'mcq', '["Une répétition dont on connaît le nombre de tours d’avance","Une répétition sans fin","Une répétition qui dépend d’un capteur","Une instruction unique"]'::jsonb, 0, '« Répéter 10 fois » en est une.', 3),
    ('6f895d90-a9fc-555b-ae21-c14e8ce5c03c'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'À quoi sert une variable ?', 'mcq', '["À stocker une valeur susceptible de changer","À répéter des instructions","À comparer deux nombres","À commander un moteur"]'::jsonb, 0, 'Compteur, mesure, score : elle porte un nom et une valeur.', 4),
    ('29f7af16-7908-54bd-93d0-10cdd241bfc7'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Que fait l’opérateur logique « et » ?', 'mcq', '["Il exige que les deux conditions soient vraies","Il exige qu’au moins une condition soit vraie","Il inverse une condition","Il additionne deux nombres"]'::jsonb, 0, '« si porte fermée et code correct ».', 5),
    ('9248498d-5fe8-5304-a4a9-04fe8d881f70'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Qu’est-ce qu’une boucle infinie ?', 'mcq', '["Une boucle dont la condition d’arrêt n’est jamais atteinte","Une boucle qui s’exécute une seule fois","Une boucle qui contient une condition","Une boucle correctement bornée"]'::jsonb, 0, 'C’est l’erreur la plus fréquente du débutant.', 6),
    ('350a4000-165b-558f-a692-e87e1ca7ff17'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Comment appelle-t-on la représentation graphique d’un algorithme ?', 'mcq', '["Un organigramme","Un tableau comparatif","Un diagramme des interacteurs","Un schéma cinématique"]'::jsonb, 0, 'Losanges pour les tests, rectangles pour les actions.', 7),
    ('e0b25e21-a43d-5579-b6ba-aac86d2a63de'::uuid, 'ea990c04-d6e3-5665-9742-77bd8e78c975'::uuid, 'Un algorithme dépend du langage de programmation utilisé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se traduit ensuite dans n’importe quel langage : c’est la logique qui compte.', 8),
    ('2966c1f9-08cd-524b-b3b2-6706924422d9'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Quel est l’avantage principal de la programmation par blocs ?', 'mcq', '["Aucune faute de syntaxe n’est possible","Elle s’exécute plus vite","Elle permet des programmes plus longs","Elle est plus facile à partager par texte"]'::jsonb, 0, 'Les blocs incompatibles ne s’emboîtent tout simplement pas.', 1),
    ('b726841e-57ba-5989-b3c3-0f82229ef4dd'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Quel logiciel relève de la programmation graphique ?', 'mcq', '["Scratch","Python","C++","JavaScript"]'::jsonb, 0, 'mBlock et Blockly également.', 2),
    ('6ae9027f-62cb-56a4-9570-151697899140'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Quelle est la principale difficulté de la programmation textuelle ?', 'mcq', '["La syntaxe, très stricte","L’impossibilité de faire des boucles","L’absence de variables","La lenteur d’exécution"]'::jsonb, 0, 'Un deux-points ou une indentation oubliés bloquent l’exécution.', 3),
    ('e75376a0-549a-558d-aa81-909ab3e8c8c4'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'En Python, que signale l’indentation ?', 'mcq', '["Ce qui appartient au bloc en cours","La fin du programme","Un commentaire","Une erreur de frappe"]'::jsonb, 0, 'Elle fait partie du langage, ce n’est pas une mise en forme.', 4),
    ('bbd54033-e70e-5947-87a6-32b61785739f'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Que change le passage des blocs au texte pour l’algorithme ?', 'mcq', '["Rien : séquence, condition, boucle et variable sont les mêmes","Tout : la logique doit être repensée","Les variables disparaissent","Les boucles deviennent impossibles"]'::jsonb, 0, 'Seule l’écriture change.', 5),
    ('bc74eb07-3827-52ea-817b-66076675ab6a'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Quel caractère termine en Python la ligne qui ouvre un bloc ?', 'mcq', '["Le deux-points","Le point-virgule","L’accolade","La parenthèse"]'::jsonb, 0, 'Il annonce le bloc indenté qui suit.', 6),
    ('31819567-1bf1-5e83-bd64-04b38dff5c82'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Quel avantage la programmation textuelle offre-t-elle pour le travail en équipe ?', 'mcq', '["Le code se copie, se compare et se partage facilement","Elle se lit sans aucune formation","Elle interdit toute erreur","Elle ne nécessite pas d’ordinateur"]'::jsonb, 0, 'Un fichier texte se versionne, pas un assemblage de blocs.', 7),
    ('555cfaa7-ec55-554b-997c-f62519fa500c'::uuid, 'ef6045a9-153a-5e60-b7eb-bc38e065da4c'::uuid, 'Un programme écrit en blocs ne peut pas piloter une carte programmable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'mBlock et les environnements dérivés pilotent très bien une carte.', 8),
    ('7ed5bfb0-63ed-55fb-a1ac-16ff76daab40'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Que faut-il faire avant d’écrire le programme ?', 'mcq', '["Analyser le besoin et écrire l’algorithme","Choisir la couleur de l’interface","Acheter la carte programmable","Tester le programme"]'::jsonb, 0, 'L’algorithme se pense avant de toucher au clavier.', 1),
    ('c4d2e0cc-ad94-53bd-a0eb-0f8b5d5d140f'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Comment appelle-t-on la recherche et la correction des erreurs ?', 'mcq', '["Le débogage","La compilation","L’exécution","La documentation"]'::jsonb, 0, 'Elle alterne avec les tests jusqu’à conformité.', 2),
    ('612e9655-edb2-57ce-9a00-646e4e700fc6'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Quelle erreur empêche le programme de démarrer ?', 'mcq', '["L’erreur de syntaxe","L’erreur de logique","L’erreur d’ergonomie","L’erreur de câblage"]'::jsonb, 0, 'Le message d’erreur indique généralement la ligne fautive.', 3),
    ('aeb7ef65-b7c4-517a-b565-2524d9f5e6de'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Quelle erreur est la plus difficile à détecter ?', 'mcq', '["L’erreur de logique","L’erreur de syntaxe","L’erreur d’orthographe dans un commentaire","L’erreur de nom de fichier"]'::jsonb, 0, 'Le programme s’exécute sans message, mais fait autre chose que prévu.', 4),
    ('cea75648-215c-5ed1-bceb-466fe6b3f4aa'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Qu’est-ce qu’un jeu d’essai ?', 'mcq', '["Un ensemble de cas de test préparés à l’avance","Une partie du programme non utilisée","Un jeu vidéo de démonstration","Une simulation graphique"]'::jsonb, 0, 'Un cas normal, un cas limite, un cas interdit.', 5),
    ('5f482703-7917-5c36-bcd1-826190f426f5'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Pourquoi tester les cas limites ?', 'mcq', '["Parce que ce sont eux qui révèlent les défauts","Parce qu’ils sont plus rapides à exécuter","Parce qu’ils sont exigés par la norme","Parce qu’ils simplifient le code"]'::jsonb, 0, 'Un programme qui marche une fois n’est pas validé.', 6),
    ('d3b5cdf6-26f3-5e8f-92b6-f6b5f36549e8'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Pourquoi commenter et nommer clairement ses variables ?', 'mcq', '["Pour rendre le programme modifiable par un autre, ou par soi plus tard","Pour accélérer l’exécution","Pour réduire la taille du fichier","Pour éviter les erreurs de syntaxe"]'::jsonb, 0, 'Un nom explicite vaut mieux qu’un commentaire.', 7),
    ('787caa06-8816-5f28-8a8b-5aed8dcca104'::uuid, '03d68480-0225-5e64-aef3-c3a19eaac4a3'::uuid, 'Un programme sans message d’erreur fonctionne forcément correctement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une erreur de logique s’exécute sans rien signaler.', 8),
    ('7d9a2eb3-1af1-5833-8619-4fe4f79daaaf'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Quelle différence y a-t-il entre une donnée et une information ?', 'mcq', '["L’information est une donnée interprétée dans un contexte","La donnée est toujours un texte","L’information est plus courte","Ce sont deux mots pour la même chose"]'::jsonb, 0, '« 18 » est une donnée ; « 18 °C dans le local » est une information.', 1),
    ('5fdb9e77-0aee-5146-9daa-67601bff9713'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Dans un tableau de données, que représente une ligne ?', 'mcq', '["Un enregistrement","Un champ","Une clé","Un type de données"]'::jsonb, 0, 'Les colonnes, elles, sont les champs.', 2),
    ('f34b7dcd-10e7-5c88-9d2a-9fe3577aae64'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'À quoi sert une clé dans un tableau de données ?', 'mcq', '["À identifier chaque ligne sans ambiguïté","À trier les colonnes","À protéger le fichier","À convertir les unités"]'::jsonb, 0, 'Deux enregistrements ne peuvent pas partager la même clé.', 3),
    ('c74ee42f-ac8f-5694-be06-167b422dffbe'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Que fait un filtre sur un jeu de données ?', 'mcq', '["Il ne garde que les lignes vérifiant une condition","Il range les lignes par ordre croissant","Il calcule une moyenne","Il supprime les doublons automatiquement"]'::jsonb, 0, 'Le tri, lui, range sans rien enlever.', 4),
    ('86a7dc08-35a5-5eaf-83b2-dec4be3103e9'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Quel graphique convient pour représenter une évolution dans le temps ?', 'mcq', '["Une courbe","Un camembert","Un tableau croisé","Un diagramme de Venn"]'::jsonb, 0, 'Le camembert représente des parts d’un tout.', 5),
    ('b8878697-0cec-5a8b-8b56-b740fd3d3f92'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Qu’est-ce qu’un fichier CSV ?', 'mcq', '["Un tableau en texte, avec des champs séparés par des virgules ou points-virgules","Une image compressée","Un programme exécutable","Un format de vidéo"]'::jsonb, 0, 'Simple et lisible par tous les tableurs.', 6),
    ('89566266-b1fe-54de-bfa8-42e4c3a79da3'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Pourquoi vérifier les valeurs extrêmes d’un jeu de données ?', 'mcq', '["Parce qu’une valeur aberrante fausse tout le traitement","Parce qu’elles sont toujours fausses","Parce qu’elles ralentissent le calcul","Parce qu’elles doivent être supprimées systématiquement"]'::jsonb, 0, 'Une unité oubliée ou une saisie erronée se repère souvent là.', 7),
    ('f3a774f3-61aa-5a22-83d3-70a3838b0503'::uuid, 'cd42709d-a2ee-5d31-9197-a64da3b5f548'::uuid, 'Le choix du type de graphique n’a aucune conséquence sur la lecture des données.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une courbe raconte une évolution, un camembert une répartition : se tromper change le message.', 8),
    ('bb56725a-7e49-5bce-a667-b0e06c7d0315'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'Qu’est-ce qu’un système d’information ?', 'mcq', '["L’ensemble matériel, logiciel, données, procédures et utilisateurs qui traite l’information","Un ordinateur puissant","Un logiciel de base de données","Un réseau de câbles"]'::jsonb, 0, 'Il collecte, stocke, traite et diffuse des données.', 1),
    ('3dcff7e4-d3b7-564d-8ea8-a55dcdf90fe9'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'Qu’est-ce que le stockage « dans le nuage » ?', 'mcq', '["Un stockage sur les serveurs d’un prestataire, accessible par Internet","Un stockage sans support physique","Un stockage sur une clé USB","Un stockage temporaire dans la mémoire vive"]'::jsonb, 0, 'Ce sont des centres de données bien réels, gourmands en énergie.', 2),
    ('b38fcea6-0e14-5914-86e1-350411b1179d'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'À combien d’octets correspond 1 Go ?', 'mcq', '["10⁹ octets","10⁶ octets","10³ octets","10¹² octets"]'::jsonb, 0, 'Un film pèse quelques Go, une photo quelques Mo.', 3),
    ('0a9e1244-d839-5464-aa4d-0ba887e655bd'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'Que dit la règle de sauvegarde 3-2-1 ?', 'mcq', '["3 copies, sur 2 supports différents, dont 1 hors du lieu principal","3 sauvegardes par jour pendant 2 semaines sur 1 disque","3 mots de passe, 2 comptes, 1 administrateur","3 To minimum, 2 disques, 1 serveur"]'::jsonb, 0, 'Et une sauvegarde jamais testée n’est pas une sauvegarde.', 4),
    ('5d35edce-db0e-5b80-92ae-93dd5a9aee7f'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'À quoi sert le chiffrement des données ?', 'mcq', '["À les rendre illisibles sans la clé","À les compresser","À les sauvegarder automatiquement","À accélérer leur transfert"]'::jsonb, 0, 'C’est la protection de dernier recours en cas de vol.', 5),
    ('cc7adb37-f24a-5d3b-862f-65b97a1df2ad'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'Que garantit le RGPD aux personnes ?', 'mcq', '["Un droit d’accès, de rectification et de suppression de leurs données","La gratuité des services en ligne","Un stockage illimité","L’anonymat total sur Internet"]'::jsonb, 0, 'Il impose aussi consentement, finalité déclarée et durée limitée.', 6),
    ('7234117f-532b-509e-bb98-618c26541e65'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'Quel est l’inconvénient principal d’un stockage uniquement local ?', 'mcq', '["Une panne, un vol ou un incendie fait tout disparaître","Il nécessite une connexion permanente","Il est toujours plus lent","Il est interdit par le RGPD"]'::jsonb, 0, 'D’où l’intérêt d’une copie hors du lieu principal.', 7),
    ('098ac738-9692-5495-80c9-d25a2a7c0b52'::uuid, 'e65bc70d-f663-5c82-815a-b3f8fd2959a8'::uuid, 'Les données stockées dans le nuage ne se trouvent sur aucun support physique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles sont sur les disques de centres de données bien réels.', 8),
    ('e62b464d-43c0-51bc-9bce-e8c62a8b3eae'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Que désigne un LAN ?', 'mcq', '["Un réseau local, limité à un bâtiment ou un site","Le réseau mondial","Un réseau sans fil uniquement","Un protocole de sécurité"]'::jsonb, 0, 'Le WAN relie, lui, plusieurs sites.', 1),
    ('ec3174a2-093c-5cb1-90eb-4c8051b62fef'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Quel équipement relie deux réseaux différents ?', 'mcq', '["Le routeur","Le switch","Le serveur","La carte réseau"]'::jsonb, 0, 'Le switch, lui, aiguille au sein d’un même réseau local.', 2),
    ('5a058a3b-906a-5297-b169-ecb88985b0a0'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'À quoi sert une adresse IP ?', 'mcq', '["À identifier une machine sur le réseau","À chiffrer les données","À mesurer le débit","À stocker les fichiers"]'::jsonb, 0, 'Elle joue le rôle d’une adresse postale.', 3),
    ('67992b31-5e5a-56dc-9a03-b829b1104420'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Que fait le DNS ?', 'mcq', '["Il traduit un nom de site en adresse IP","Il chiffre les communications","Il découpe les messages en paquets","Il distribue les adresses IP locales"]'::jsonb, 0, 'Sans lui, il faudrait retenir des suites de chiffres.', 4),
    ('faa9da9e-6e43-504d-821a-cd0ffb4ef4e2'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Que signifie le S de HTTPS ?', 'mcq', '["L’échange est chiffré, donc sécurisé","Le site est un serveur","La connexion est plus rapide","Le site est officiel"]'::jsonb, 0, 'Le contenu échangé devient illisible pour un intercepteur.', 5),
    ('c6f4e8f9-db8f-5050-8ba1-c52d8364d2fa'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Comment un message circule-t-il sur Internet ?', 'mcq', '["Découpé en paquets numérotés, réassemblés à l’arrivée","D’un seul bloc, par un chemin unique","Uniquement par câble","Toujours par le même serveur central"]'::jsonb, 0, 'Si un chemin est coupé, les paquets passent par un autre.', 6),
    ('345b8424-cd82-5566-a348-e77358ea76e8'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Quel équipement réunit routeur, switch, modem et point d’accès Wi-Fi ?', 'mcq', '["La box","Le serveur","Le commutateur seul","La carte mère"]'::jsonb, 0, 'C’est le boîtier présent dans la plupart des foyers.', 7),
    ('5e308ad0-69d7-59c2-b967-70759758f897'::uuid, 'f20751a0-70fd-5364-a9e3-5116c2d034bc'::uuid, 'Une connexion Wi-Fi est plus sûre qu’une connexion filaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le signal se diffuse dans l’air : il est plus exposé aux interceptions.', 8),
    ('c210105f-a1da-5e9c-ac72-a3f1db811266'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Qu’est-ce qu’un projet technique ?', 'mcq', '["Un ensemble d’actions coordonnées avec un objectif, un délai et des moyens limités","La fabrication d’un objet unique","Un dessin technique détaillé","Un cahier des charges"]'::jsonb, 0, 'Il se découpe en phases puis en tâches.', 1),
    ('1b55d533-c01c-5d27-b97c-1f0dfcfd8fa0'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Quelle est la première phase d’un projet ?', 'mcq', '["L’analyse du besoin et le cahier des charges","La réalisation du prototype","Les tests de validation","Le bilan"]'::jsonb, 0, 'On ne conçoit rien avant de savoir ce qui est demandé.', 2),
    ('5799a676-ee69-5505-a56b-fcefc4d28388'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Que représente un diagramme de Gantt ?', 'mcq', '["Les tâches et leur durée dans le temps","Les fonctions de l’objet","Les interacteurs du système","Le budget du projet"]'::jsonb, 0, 'Chaque tâche est une barre horizontale.', 3),
    ('d2bd44ea-b9f3-54fa-a1d7-cc2457bf2d93'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Qu’est-ce qu’une antériorité entre deux tâches ?', 'mcq', '["Une tâche qui doit être finie avant qu’une autre commence","Une tâche facultative","Une tâche déjà réalisée dans un projet précédent","Une tâche sans responsable"]'::jsonb, 0, 'Elle contraint l’ordre du planning.', 4),
    ('a6ba920f-72ce-5968-aebb-648d7fc09176'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Qu’est-ce que le chemin critique ?', 'mcq', '["La suite de tâches dont tout retard décale la fin du projet","La tâche la plus difficile","La tâche la plus coûteuse","Le trajet des pièces dans l’atelier"]'::jsonb, 0, 'Les autres tâches disposent d’une marge.', 5),
    ('e1e03946-519c-54ae-991c-e0ef3480f514'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'À quoi sert une revue de projet ?', 'mcq', '["À faire le point en équipe et corriger la trajectoire","À valider le produit auprès du client final","À commander les matériaux","À rédiger la notice"]'::jsonb, 0, 'Elle se tient régulièrement, pas seulement à la fin.', 6),
    ('07f63f2d-4326-569b-86ff-3133adf2d3c4'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Pourquoi documenter un essai raté ?', 'mcq', '["Pour éviter qu’un autre refasse la même erreur","Pour justifier le retard","Parce que la norme l’exige","Pour augmenter le nombre de pages du dossier"]'::jsonb, 0, 'Un essai raté documenté vaut mieux qu’un succès inexpliqué.', 7),
    ('dcd9557e-2dc2-50f1-a1ec-42d7f842b631'::uuid, 'ad4a26f6-cf1c-596b-be1d-5f86de814976'::uuid, 'Toutes les tâches d’un projet doivent se dérouler l’une après l’autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Beaucoup se mènent en parallèle : c’est ce que montre le diagramme de Gantt.', 8),
    ('c1dfa320-fcdc-5768-8fde-2dcda48ba738'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Qu’est-ce qu’un croquis ?', 'mcq', '["Un dessin à main levée, rapide, pour fixer une idée","Un dessin normalisé à l’échelle","Un schéma électrique","Un modèle 3D simplifié"]'::jsonb, 0, 'Ni à l’échelle, ni normalisé : c’est ce qui le rend rapide.', 1),
    ('482ccd0c-39a0-542d-b739-08ade78077e8'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Que représente un schéma cinématique ?', 'mcq', '["Les liaisons entre pièces et les mouvements possibles","Le circuit électrique","Les dimensions réelles de l’objet","Le planning du projet"]'::jsonb, 0, 'Il décrit le fonctionnement mécanique, pas la forme.', 2),
    ('9fad9768-4e0d-5899-8f13-471fd4e5de6a'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Que signifie une échelle 1:2 ?', 'mcq', '["Le dessin est deux fois plus petit que l’objet réel","Le dessin est deux fois plus grand","Le dessin est à taille réelle","L’objet mesure 2 mm"]'::jsonb, 0, 'Une échelle 2:1 serait deux fois plus grande que le réel.', 3),
    ('2f8b5f0d-09e1-57ad-8b3a-88cfa7299425'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Que donne la cotation d’un dessin technique ?', 'mcq', '["Les dimensions réelles de l’objet, en millimètres","La liste des matériaux","Le nom du concepteur","Le prix de fabrication"]'::jsonb, 0, 'Elle rend le dessin exploitable par le fabricant.', 4),
    ('6c01dd16-8bf1-5a35-8dd5-931d1e3631b4'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Que signifie un trait interrompu sur un dessin technique ?', 'mcq', '["Une arête cachée","Une arête vue","Un axe de symétrie","Une cote"]'::jsonb, 0, 'Le trait continu fort marque les arêtes vues.', 5),
    ('95252b1b-5783-55c7-bf74-59b22aea058a'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Que permet la modélisation 3D avant toute fabrication ?', 'mcq', '["Simuler les mouvements et détecter les interférences entre pièces","Réduire le prix des matériaux","Supprimer les tests de validation","Éviter le cahier des charges"]'::jsonb, 0, 'Elle permet aussi d’exporter vers une imprimante 3D ou une MOCN.', 6),
    ('e1c2a795-8002-5ab6-a1c4-0071f293c3f7'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Quelle représentation sert à faire fabriquer une pièce ?', 'mcq', '["Le dessin technique coté et à l’échelle","Le croquis à main levée","Le schéma de principe","Le diagramme de Gantt"]'::jsonb, 0, 'C’est un document contractuel entre concepteur et fabricant.', 7),
    ('17144abf-7f5c-5c61-a7b7-a34c16998f78'::uuid, '257db352-da76-5e22-b1cc-7f41db35aa5e'::uuid, 'Un croquis doit toujours être réalisé à l’échelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est justement sa liberté qui en fait un outil de recherche rapide.', 8),
    ('cc5027d4-87d2-5a8e-8ead-0fe80c91d8d7'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Par quoi commence toute démarche de conception ?', 'mcq', '["L’analyse du besoin et le cahier des charges","Le choix du matériau","La fabrication du prototype","La rédaction de la notice"]'::jsonb, 0, 'On ne conçoit pas avant de savoir ce qui est demandé.', 1),
    ('216bb39e-d167-55a2-be74-2608e839120e'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Pourquoi chercher plusieurs solutions avant de choisir ?', 'mcq', '["Parce qu’une seule idée n’est pas un choix","Pour allonger la durée du projet","Parce que la norme l’impose","Pour utiliser tous les matériaux disponibles"]'::jsonb, 0, 'La comparaison est ce qui rend le choix justifiable.', 2),
    ('24a3f46a-867e-570d-9bce-f4fcf006ef67'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Qu’est-ce qu’une nomenclature ?', 'mcq', '["La liste des pièces avec quantités et références","Le planning du projet","La liste des utilisateurs","Le nom commercial de l’objet"]'::jsonb, 0, 'Elle accompagne les dessins de conception.', 3),
    ('9af5c2ea-385f-52df-b636-db3b32c1ee83'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Qu’est-ce qu’une gamme de fabrication ?', 'mcq', '["L’ordre des opérations pour réaliser une pièce","La gamme de prix du produit","La liste des fournisseurs","L’ensemble des variantes du produit"]'::jsonb, 0, 'Elle précise machines, outils et règles de sécurité.', 4),
    ('e2359c4d-2dd2-5340-9eef-d36d63541b3c'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Pourquoi contrôler les pièces au fur et à mesure ?', 'mcq', '["Parce qu’un défaut détecté tôt coûte beaucoup moins cher","Pour occuper le temps d’attente","Parce que le client l’exige","Pour éviter la nomenclature"]'::jsonb, 0, 'Un assemblage terminé avec une pièce hors cote est à refaire entièrement.', 5),
    ('07b45b66-5a65-5279-87f3-5ceb2ea8e3ac'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Que signifie une démarche itérative ?', 'mcq', '["Elle revient en arrière quand un test échoue ou qu’une contrainte change","Elle suit un ordre strict et immuable","Elle se fait sans tests","Elle ne concerne que la fabrication"]'::jsonb, 0, 'Un test raté renvoie à la conception.', 6),
    ('e8de7a69-4e7a-5bf3-8611-61e044eaf841'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'Que contient la documentation finale d’un projet ?', 'mcq', '["Dossier de conception, plans, nomenclature, programme et notice","Uniquement la facture des matériaux","Uniquement les photos de l’objet","Uniquement le cahier des charges"]'::jsonb, 0, 'Elle prouve la maîtrise de la démarche autant que l’objet lui-même.', 7),
    ('e98530bb-e61c-51f7-8358-bdbecfad949b'::uuid, 'e535480d-c66f-51c9-8a47-10e80b56161c'::uuid, 'La démarche de conception se déroule toujours en ligne droite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est itérative : on revient en arrière dès qu’un test ou une contrainte l’impose.', 8),
    ('21e3fd00-f348-5b6c-bd33-b58ab669f8dc'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Quelle différence y a-t-il entre tester et valider ?', 'mcq', '["Tester mesure, valider compare la mesure à l’exigence","Tester compare, valider mesure","Ce sont deux mots pour la même chose","Tester concerne le prototype, valider la série"]'::jsonb, 0, 'La validation conclut : conforme ou non conforme.', 1),
    ('c864c930-eefc-572a-8540-811940f067bc'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Quel essai consiste à tirer sur une pièce jusqu’à la rupture ?', 'mcq', '["L’essai de traction","L’essai de compression","L’essai de flexion","L’essai de torsion"]'::jsonb, 0, 'La compression, elle, écrase la pièce.', 2),
    ('52445ea1-b2b2-58ca-9b51-4b929de291ea'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Quel essai révèle une rupture due à la répétition d’un effort ?', 'mcq', '["L’essai de fatigue","L’essai de traction","L’essai de dureté","L’essai d’étanchéité"]'::jsonb, 0, 'Beaucoup de pièces cassent par répétition, pas par excès d’effort.', 3),
    ('96466cd2-e17b-5201-b6fa-ef0c57244a09'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Que doit contenir un protocole d’essai ?', 'mcq', '["La grandeur mesurée, l’instrument, les conditions et le mode opératoire","Uniquement le résultat final","Le nom du fabricant","Le prix de l’objet testé"]'::jsonb, 0, 'C’est ce qui rend l’essai reproductible.', 4),
    ('be026181-3520-522b-9e3c-99dda61c8bca'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Que calcule une simulation numérique sur un modèle 3D ?', 'mcq', '["Les contraintes, les déformations et les zones de rupture probables","Le prix de revient","La durée de fabrication","Le nombre d’utilisateurs"]'::jsonb, 0, 'Elle permet d’essayer plusieurs formes sans rien fabriquer.', 5),
    ('9f008c68-624d-5b8c-9fc7-1313d22bde8c'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Quelle est la limite de la simulation numérique ?', 'mcq', '["Elle repose sur des hypothèses et ne remplace pas l’essai réel","Elle est toujours plus lente qu’un essai","Elle ne fonctionne que sur les métaux","Elle ne donne aucun résultat chiffré"]'::jsonb, 0, 'Un modèle est une représentation, pas la réalité.', 6),
    ('543727b1-3f54-5408-a38d-c9cf1fc4becf'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Que fait-on en cas de non-conformité ?', 'mcq', '["On revient à la conception pour corriger","On ajuste le cahier des charges au résultat obtenu","On refait le même essai jusqu’à réussir","On livre l’objet en le signalant"]'::jsonb, 0, 'C’est le retour de boucle de la démarche itérative.', 7),
    ('0a0830c9-b904-5c07-8823-a0113ef88c33'::uuid, '954af929-2128-5885-a048-77b52971190d'::uuid, 'Un résultat d’essai se suffit à lui-même, sans ses conditions.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Il tient 40 kg » ne veut rien dire sans savoir comment la charge a été appliquée.', 8),
    ('958cce95-238b-5529-9e5d-46e9834328b2'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Qu’est-ce qu’un prototype ?', 'mcq', '["Un premier exemplaire fabriqué pour vérifier une solution","Le produit final vendu au client","Un dessin en trois dimensions","Un cahier des charges illustré"]'::jsonb, 0, 'Il sert à apprendre avant de produire.', 1),
    ('479f511b-8f4e-5dd6-87ea-d8e158f0a563'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Qu’est-ce qu’une maquette ?', 'mcq', '["Un modèle à l’échelle, non fonctionnel, qui montre la forme","Un prototype qui fonctionne","Le premier exemplaire de la série","Un dessin technique coté"]'::jsonb, 0, 'Elle sert à juger l’encombrement et l’aspect.', 2),
    ('171d388a-5414-5ae1-baee-5d713f76aa42'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Qu’est-ce qu’un prototype fonctionnel ?', 'mcq', '["Un exemplaire qui fonctionne, avec des matériaux différents de la série","Une maquette en carton","Le produit final","Un modèle numérique"]'::jsonb, 0, 'Il valide la solution, pas encore le procédé de fabrication.', 3),
    ('f1988112-6db4-50ba-b2d6-b915e493714c'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Quel moyen permet de fabriquer rapidement une pièce de forme complexe ?', 'mcq', '["L’impression 3D","Le moulage par injection","L’emboutissage","Le forgeage"]'::jsonb, 0, 'Une pièce à la fois, en quelques heures.', 4),
    ('4275d9d9-541d-590b-80d6-c281b9de3a71'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Pourquoi montrer un prototype à l’utilisateur ?', 'mcq', '["Parce que son avis sur un objet réel est bien plus riche que sur un dessin","Pour lui faire signer le cahier des charges","Pour fixer le prix de vente","Parce que la norme l’impose"]'::jsonb, 0, 'On y détecte des problèmes d’usage invisibles sur le papier.', 5),
    ('4bfe92e0-269d-5d01-91b8-71ae6cd2aa98'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Que signifie itérer en prototypage ?', 'mcq', '["Enchaîner prototype, test, analyse, modification et nouveau prototype","Fabriquer plusieurs exemplaires identiques","Répéter le même essai","Produire en série"]'::jsonb, 0, 'Chaque tour coûte du temps mais en fait gagner beaucoup plus.', 6),
    ('64f9ab1a-2ddc-5d82-90be-a90fa94c68da'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Pourquoi une erreur détectée sur un prototype coûte-t-elle peu ?', 'mcq', '["Parce qu’elle n’affecte qu’un exemplaire, pas toute une production","Parce que le prototype est gratuit","Parce qu’elle est toujours mineure","Parce qu’elle ne nécessite aucune correction"]'::jsonb, 0, 'La même erreur sur dix mille exemplaires vendus est cent fois plus coûteuse.', 7),
    ('e1ea8a32-208e-54a6-9d66-dbf008c8f838'::uuid, '41b37a20-471e-5a16-9055-b972b6d4b71e'::uuid, 'Un prototype qui ne fonctionne pas rend le projet inutile.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un test qui a donné son résultat : le vrai risque serait de produire sans avoir rien testé.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('technologie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('technologie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 296 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 296 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
